// ═════════ packages/engine/src/reps.ts ═════════ (pure, dependency-free; byte-identical copy at backend/src/shared/reps.ts)
// Live rep counting from MediaPipe Pose landmarks. The phone runs it on every pose sample (the live count) and the
// Keeper runs the same file on the uploaded trace (the count in the receipt). Both feed it the trace's quantised
// integers, so both get the same number.

export type Exercise = "push_up" | "squat";
/** MediaPipe Pose indices carried in the trace, in this order (left/right pairs). */
export const TRACE_JOINTS = [11, 12, 13, 14, 15, 16, 23, 24, 25, 26, 27, 28] as const;
export const TRACE_HZ_MAX = 20;
export const REP_SET_MAX_MS = 240_000;
export const REPS_ENGINE = "reps@1";
export const REP_TARGET_MAX = 50;

export type Pt = { x: number; y: number; v: number };            // normalised image coords (y down), visibility 0..1
export type Sample = { t: number; j: readonly Pt[] };             // t = ms from set start; j.length === 12

// ── Rep habit text: "20 push-ups" / "30 squats" ──
const REP_TEXT = /^([1-9]\d?) (push-ups|squats)$/;
export function parseRepHabit(text: string): { exercise: Exercise; target: number } | null {
  const m = REP_TEXT.exec(text.trim().toLowerCase());
  const target = m ? Number(m[1]) : 0;
  return m && target <= REP_TARGET_MAX ? { exercise: m[2] === "push-ups" ? "push_up" : "squat", target } : null;
}
export const repHabitText = (e: Exercise, target: number) => `${target} ${e === "push_up" ? "push-ups" : "squats"}`;

// ── Geometry (x scaled by aspect = width/height so angles are true image angles) ──
export function angleAt(a: Pt, b: Pt, c: Pt, aspect: number): number {
  const ax = (a.x - b.x) * aspect, ay = a.y - b.y, cx = (c.x - b.x) * aspect, cy = c.y - b.y;
  const n = Math.hypot(ax, ay) * Math.hypot(cx, cy);
  return n < 1e-9 ? NaN : (Math.acos(Math.max(-1, Math.min(1, (ax * cx + ay * cy) / n))) * 180) / Math.PI;
}
/** Line a→b against the horizontal: 0° flat, 90° vertical. */
export const inclineDeg = (a: Pt, b: Pt, aspect: number) => (Math.atan2(Math.abs(b.y - a.y), Math.abs((b.x - a.x) * aspect)) * 180) / Math.PI;
const dist = (a: Pt, b: Pt, aspect: number) => Math.hypot((a.x - b.x) * aspect, a.y - b.y);

export type Side = 0 | 1;
type Limb = { shoulder: Pt; elbow: Pt; wrist: Pt; hip: Pt; knee: Pt; ankle: Pt };
export const limb = (j: readonly Pt[], s: Side): Limb => ({ shoulder: j[0 + s]!, elbow: j[2 + s]!, wrist: j[4 + s]!, hip: j[6 + s]!, knee: j[8 + s]!, ankle: j[10 + s]! });
const NEEDED: Record<Exercise, (keyof Limb)[]> = { push_up: ["shoulder", "elbow", "wrist", "hip", "ankle"], squat: ["shoulder", "hip", "knee", "ankle"] };
const inFrame = (p: Pt) => p.x >= -0.02 && p.x <= 1.02 && p.y >= -0.02 && p.y <= 1.02;
/** The weakest needed joint's visibility (0 when one is out of frame): one bad joint breaks the angle. */
export function sideScore(j: readonly Pt[], s: Side, ex: Exercise): number {
  const l = limb(j, s);
  return Math.min(...NEEDED[ex].map((k) => (inFrame(l[k]) ? l[k].v : 0)));
}

export type Features = { t: number; side: Side; primary: number; bodyLine: number; knee: number; incline: number; depth: number; facing: boolean };
export function features(s: Sample, side: Side, ex: Exercise, aspect: number): Features {
  const l = limb(s.j, side), o = limb(s.j, (1 - side) as Side);
  const torso = dist(l.shoulder, l.hip, aspect);
  return {
    t: s.t, side,
    primary: ex === "push_up" ? angleAt(l.shoulder, l.elbow, l.wrist, aspect) : angleAt(l.hip, l.knee, l.ankle, aspect),
    bodyLine: ex === "push_up" ? angleAt(l.shoulder, l.hip, l.ankle, aspect) : angleAt(l.shoulder, l.hip, l.knee, aspect),
    knee: angleAt(l.hip, l.knee, l.ankle, aspect),
    incline: ex === "push_up" ? inclineDeg(l.shoulder, l.ankle, aspect) : inclineDeg(l.hip, l.shoulder, aspect),
    depth: (l.hip.y - l.knee.y) / Math.max(1e-6, dist(l.hip, l.knee, aspect)),       // > 0: hip below knee
    facing: torso > 0 && Math.abs((l.shoulder.x - o.shoulder.x) * aspect) > 0.6 * torso, // facing the camera, not side-on
  };
}

// ── Rules ──
export type Fault = "turn_side" | "not_plank" | "hips" | "knees" | "lean" | "depth" | "no_lockout";
type Rules = { attempt: number; down: number; up: number; minRepMs: number; maxRepMs: number; startHoldMs: number;
  fault(f: Features, atBottom: boolean): Fault | null; startPose(f: Features): boolean };
export const VIS_MIN = 0.5, SIDE_MARGIN = 0.15, LOST_MS = 400, EMA_TAU_MS = 60, SPIKE_DEG = 60, FAULT_SHARE = 0.25;
export const RULES: Record<Exercise, Rules> = {
  push_up: {
    attempt: 130, down: 90, up: 160, minRepMs: 600, maxRepMs: 8_000, startHoldMs: 500,
    fault: (f) => (f.facing ? "turn_side" : f.incline > 35 ? "not_plank" : f.bodyLine < 150 ? "hips" : f.knee < 140 ? "knees" : null),
    startPose: (f) => f.primary > 160 && f.incline <= 35 && f.bodyLine >= 150 && !f.facing,
  },
  squat: {
    attempt: 140, down: 100, up: 160, minRepMs: 800, maxRepMs: 10_000, startHoldMs: 500,
    fault: (f, atBottom) => (f.incline < 30 ? "lean" : atBottom && f.depth < -0.15 ? "depth" : null),
    startPose: (f) => f.primary > 160 && f.incline >= 65,
  },
};

// ── State machine ──
export type Phase = "setup" | "up" | "descending" | "down" | "lost" | "paused";
export type RepRecord = { startT: number; bottomT: number; endT: number; minAngle: number };
export type RepEvent =
  | { type: "ready"; t: number }
  | { type: "lost"; t: number }
  | { type: "bottom"; t: number; angle: number }
  | ({ type: "rep"; t: number; count: number } & RepRecord)
  | { type: "half_rep"; t: number; minAngle: number }
  | { type: "rejected"; t: number; reason: "too_fast" | "too_slow" | Fault }
  | { type: "fault"; t: number; fault: Fault };

export class RepCounter {
  phase: Phase = "setup";
  count = 0;
  angle = NaN;            // smoothed primary angle (depth gauge)
  visible = false;        // last sample usable (framing hint)
  readonly reps: RepRecord[] = [];
  private readonly r: Rules;
  private side: Side | null = null;
  private ema: number | null = null; private emaT = 0; private spikes = 0;
  private lastOkT = -Infinity; private setupSince: number | null = null;
  private repStart = 0; private bottomT = 0; private minAngle = 180; private rose = false;
  private frames = 0; private faults = new Map<Fault, number>(); private bottomFault: Fault | null = null; private lastFault: Fault | null = null;

  constructor(readonly exercise: Exercise, readonly aspect: number) { this.r = RULES[exercise]; }

  pause(): void { this.phase = "paused"; }
  resume(t: number): void { this.phase = "setup"; this.setupSince = null; this.ema = null; this.lastOkT = t; }

  push(s: Sample): RepEvent[] {
    const ev: RepEvent[] = [];
    if (this.phase === "paused") return ev;
    const f = this.read(s);
    this.visible = f !== null;
    if (!f) {
      if (s.t - this.lastOkT > LOST_MS && this.phase !== "lost" && this.phase !== "setup") { this.phase = "lost"; ev.push({ type: "lost", t: s.t }); }
      if (this.phase === "setup") this.setupSince = null;
      return ev;
    }
    if (s.t - this.lastOkT > LOST_MS) this.ema = null;   // stale after a gap
    this.lastOkT = s.t;
    const a = this.smooth(f.primary, s.t);
    if (a === null) return ev;                             // landmark flip dropped
    this.angle = a;
    const r = this.r, fs = { ...f, primary: a };
    switch (this.phase) {
      case "lost": this.phase = "setup"; this.setupSince = null; // falls through
      case "setup":
        if (r.startPose(fs)) {
          this.setupSince ??= s.t;
          if (s.t - this.setupSince >= r.startHoldMs) { this.phase = "up"; ev.push({ type: "ready", t: s.t }); }
        } else { this.setupSince = null; const x = r.fault(fs, false); if (x) this.noteFault(x, s.t, ev); }
        break;
      case "up":
        if (a < r.attempt) { this.phase = "descending"; this.startRep(s.t); this.track(fs, a, s.t, ev); }
        break;
      case "descending":
      case "down":
        this.track(fs, a, s.t, ev);
        if (this.phase === "down" && a > r.attempt) this.rose = true;
        if (this.rose && a < r.down) {                      // second dip without locking out
          ev.push({ type: "rejected", t: s.t, reason: "no_lockout" });
          this.startRep(s.t); this.minAngle = a; this.phase = "down"; this.bottomT = s.t; ev.push({ type: "bottom", t: s.t, angle: a });
        } else if (this.phase === "descending" && a < r.down) {
          this.phase = "down"; this.bottomT = s.t; ev.push({ type: "bottom", t: s.t, angle: a });
        }
        if (a > r.up) { ev.push(this.finish(s.t)); this.phase = "up"; }
        else if (s.t - this.repStart > r.maxRepMs) { ev.push({ type: "rejected", t: s.t, reason: "too_slow" }); this.phase = "setup"; this.setupSince = null; }
        break;
    }
    return ev;
  }

  private read(s: Sample): Features | null {
    const score = [sideScore(s.j, 0, this.exercise), sideScore(s.j, 1, this.exercise)];
    let side: Side = this.side ?? (score[1]! > score[0]! ? 1 : 0);
    const other = (1 - side) as Side;
    if (score[other]! > score[side]! + SIDE_MARGIN) { side = other; this.ema = null; }
    this.side = side;
    if (score[side]! < VIS_MIN) return null;
    const f = features(s, side, this.exercise, this.aspect);
    return Number.isFinite(f.primary) ? f : null;
  }
  private smooth(x: number, t: number): number | null {
    if (this.ema === null) { this.ema = x; this.emaT = t; this.spikes = 0; return x; }
    if (Math.abs(x - this.ema) > SPIKE_DEG && this.spikes < 2) { this.spikes += 1; return null; }
    this.spikes = 0;
    this.ema += (1 - Math.exp(-Math.max(0, t - this.emaT) / EMA_TAU_MS)) * (x - this.ema);
    this.emaT = t;
    return this.ema;
  }
  private startRep(t: number) { this.repStart = t; this.minAngle = 180; this.rose = false; this.frames = 0; this.faults.clear(); this.bottomFault = null; }
  private track(f: Features, a: number, t: number, ev: RepEvent[]) {
    this.frames += 1;
    if (a < this.minAngle) { this.minAngle = a; this.bottomFault = this.r.fault(f, true) === "depth" ? "depth" : null; }
    const x = this.r.fault(f, false);
    if (x) { this.faults.set(x, (this.faults.get(x) ?? 0) + 1); this.noteFault(x, t, ev); } else this.lastFault = null;
  }
  private noteFault(x: Fault, t: number, ev: RepEvent[]) { if (x !== this.lastFault) ev.push({ type: "fault", t, fault: x }); this.lastFault = x; }
  private finish(t: number): RepEvent {
    if (this.phase === "descending") return { type: "half_rep", t, minAngle: this.minAngle };
    if (t - this.repStart < this.r.minRepMs) return { type: "rejected", t, reason: "too_fast" };
    if (this.bottomFault) return { type: "rejected", t, reason: this.bottomFault };
    const worst = [...this.faults].sort((a, b) => b[1] - a[1])[0];
    if (worst && worst[1] / Math.max(1, this.frames) > FAULT_SHARE) return { type: "rejected", t, reason: worst[0] };
    this.count += 1;
    const rec: RepRecord = { startT: this.repStart, bottomT: this.bottomT, endT: t, minAngle: this.minAngle };
    this.reps.push(rec);
    return { type: "rep", t, count: this.count, ...rec };
  }
}

// ── Trace: what the phone records and the server recounts ──
export type Trace = { v: 1; engine: typeof REPS_ENGINE; exercise: Exercise; aspect: number; t: number[]; p: number[]; pauses: [number, number][] };
const fin = (x: number) => (Number.isFinite(x) ? x : 0);

/** Phone side: throttles to ≤20 Hz, quantises, records, counts. Pause/resume apply at the next sample (replayable). */
export class RepSession {
  readonly counter: RepCounter;
  readonly aspect: number;
  private t: number[] = []; private p: number[] = []; private pauses: [number, number][] = [];
  private pending: "pause" | "resume" | null = null; private t0: number | null = null; private lastAbs = -Infinity;
  constructor(readonly exercise: Exercise, aspect: number) { this.aspect = Math.round(aspect * 1000) / 1000; this.counter = new RepCounter(exercise, this.aspect); }
  requestPause() { this.pending = "pause"; }
  requestResume() { this.pending = "resume"; }
  /** tAbs: the frame's monotonic ms (native); raw: 36 floats x,y,v in TRACE_JOINTS order (zeros when no pose). Returns null if throttled. */
  push(tAbs: number, raw: ArrayLike<number>): RepEvent[] | null {
    if (tAbs - this.lastAbs < 1000 / TRACE_HZ_MAX - 2) return null;
    this.lastAbs = tAbs; this.t0 ??= tAbs;
    const t = Math.round(tAbs - this.t0);
    const j: Pt[] = [];
    for (let i = 0; i < 12; i++) {
      const xi = Math.round(fin(raw[i * 3]!) * 1000), yi = Math.round(fin(raw[i * 3 + 1]!) * 1000), vi = Math.round(fin(raw[i * 3 + 2]!) * 100);
      this.p.push(xi, yi, vi); j.push({ x: xi / 1000, y: yi / 1000, v: vi / 100 });
    }
    this.t.push(t);
    if (this.pending === "pause") { this.pauses.push([t, Infinity]); this.counter.pause(); }
    else if (this.pending === "resume") { const last = this.pauses[this.pauses.length - 1]; if (last) last[1] = t; this.counter.resume(t); }
    this.pending = null;
    return this.counter.push({ t, j });
  }
  /** The sample time of the latest frame (absolute), for native keyframe lookup. */
  get lastFrameAbs() { return this.lastAbs; }
  trace(): Trace {
    const end = (this.t[this.t.length - 1] ?? 0) + 1;
    return { v: 1, engine: REPS_ENGINE, exercise: this.exercise, aspect: this.aspect, t: [...this.t], p: [...this.p], pauses: this.pauses.map(([a, b]) => [a, Number.isFinite(b) ? b : end]) };
  }
}

/** Validates a trace from the wire and rebuilds its samples; null when malformed. */
export function decodeTrace(raw: unknown): { trace: Trace; samples: Sample[] } | null {
  const tr = raw as Trace;
  if (!tr || tr.v !== 1 || tr.engine !== REPS_ENGINE || (tr.exercise !== "push_up" && tr.exercise !== "squat")) return null;
  if (typeof tr.aspect !== "number" || !(tr.aspect >= 0.3 && tr.aspect <= 3) || !Array.isArray(tr.t) || !Array.isArray(tr.p) || !Array.isArray(tr.pauses)) return null;
  const n = tr.t.length;
  if (n < 10 || n > (REP_SET_MAX_MS / 1000) * TRACE_HZ_MAX + 1 || tr.p.length !== n * 36 || tr.pauses.length > 1) return null;
  const samples: Sample[] = [];
  for (let i = 0; i < n; i++) {
    const t = tr.t[i]!;
    if (!Number.isInteger(t) || (i > 0 && t - tr.t[i - 1]! < 1000 / TRACE_HZ_MAX - 3)) return null;
    const j: Pt[] = [];
    for (let k = 0; k < 12; k++) {
      const x = tr.p[i * 36 + k * 3]!, y = tr.p[i * 36 + k * 3 + 1]!, v = tr.p[i * 36 + k * 3 + 2]!;
      if (!Number.isInteger(x) || !Number.isInteger(y) || !Number.isInteger(v) || Math.abs(x) > 3000 || Math.abs(y) > 3000 || v < 0 || v > 100) return null;
      j.push({ x: x / 1000, y: y / 1000, v: v / 100 });
    }
    samples.push({ t, j });
  }
  if (tr.pauses.some((pz) => !Array.isArray(pz) || !Number.isInteger(pz[0]) || !Number.isInteger(pz[1]) || pz[1] <= pz[0])) return null;
  return { trace: tr, samples };
}

/** The same count the phone showed: replays samples with the recorded pause windows. */
export function countReps(samples: readonly Sample[], exercise: Exercise, aspect: number, pauses: readonly [number, number][] = []) {
  const c = new RepCounter(exercise, aspect), events: RepEvent[] = [];
  let p = 0;
  for (const s of samples) {
    while (p < pauses.length && s.t >= pauses[p]![1]) { if (c.phase === "paused") c.resume(s.t); p += 1; }
    if (p < pauses.length && s.t >= pauses[p]![0]) { if (c.phase !== "paused") c.pause(); continue; }
    events.push(...c.push(s));
  }
  return { count: c.count, reps: c.reps, events };
}

/** Raw primary angle at one sample (better-seen side), for keyframe/phase cross-checks. */
export function rawAngleAt(s: Sample, ex: Exercise, aspect: number): number {
  const side: Side = sideScore(s.j, 1, ex) > sideScore(s.j, 0, ex) ? 1 : 0;
  return features(s, side, ex, aspect).primary;
}

/** Server-side plausibility. `hard` fails the set without a model call; `soft` only goes in the receipt. */
export function plausibility(
  samples: readonly Sample[], trace: Trace, counted: ReturnType<typeof countReps>,
  o: { target: number; windowMs: number; freeze: { afterRep: number; t: number }; keyframes: { kind: "bottom" | "top"; t: number }[] },
): { hard: string[]; soft: string[] } {
  const hard: string[] = [], soft: string[] = [], r = RULES[trace.exercise], ex = trace.exercise;
  const dur = samples[samples.length - 1]!.t - samples[0]!.t;
  if (counted.count < o.target) hard.push("count_below_target");
  if (dur > Math.min(REP_SET_MAX_MS, o.windowMs)) hard.push("longer_than_challenge_window");
  for (let i = 1; i < samples.length; i++) if (samples[i]!.t - samples[i - 1]!.t > 1000) { hard.push("camera_gap"); break; }
  const pz = trace.pauses[0];
  const k = o.freeze.afterRep, before = counted.reps[k - 1], after = counted.reps[k];
  if (!pz || pz[1] - pz[0] < 2000 || pz[1] - pz[0] > 8000) hard.push("freeze_pause_bad");
  else if (k < Math.max(1, Math.ceil(o.target * 0.3)) || k > Math.ceil(o.target * 0.7) || !before || before.endT > pz[0] || (after && after.startT < pz[1]) || o.freeze.t < pz[0] || o.freeze.t > pz[1]) hard.push("freeze_misplaced");
  const at = new Map(samples.map((s) => [s.t, s]));
  for (const kf of o.keyframes) {
    const s = at.get(kf.t);
    const a = s ? rawAngleAt(s, ex, trace.aspect) : NaN;
    if (!Number.isFinite(a) || (kf.kind === "bottom" ? a > r.down + 15 : a < r.up - 15)) { hard.push(`keyframe_${kf.kind}_mismatch`); break; }
  }
  const durs = counted.reps.map((x) => x.endT - x.startT);
  const mean = durs.reduce((a, b) => a + b, 0) / Math.max(1, durs.length);
  const cv = Math.sqrt(durs.reduce((a, b) => a + (b - mean) ** 2, 0) / Math.max(1, durs.length)) / Math.max(1, mean);
  if (durs.length >= 5 && cv < 0.04) soft.push("metronomic_tempo");
  const lens = samples.map((s) => { const sd: Side = sideScore(s.j, 1, ex) > sideScore(s.j, 0, ex) ? 1 : 0; const l = limb(s.j, sd); return ex === "push_up" ? dist(l.shoulder, l.elbow, trace.aspect) : dist(l.hip, l.knee, trace.aspect); }).filter((x) => x > 0.01);
  const lm = lens.reduce((a, b) => a + b, 0) / Math.max(1, lens.length);
  if (lens.length && Math.max(...lens.map((x) => Math.abs(x - lm) / lm)) > 0.3) soft.push("bone_length_unstable");
  return { hard, soft };
}

